#include <bits/stdc++.h>
using namespace std;

const int N = 12;
const int INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

int n, t;
char a[N][N], b[N][N];
int sx, sy;
int dist[N][N];

void bfsDist() {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist[i][j] = INF;
    bool vis[N][N] = {};
    queue<pair<int,int>> q;
    vis[sx][sy] = true;
    dist[sx][sy] = 0;
    q.emplace(sx, sy);
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny] && isdigit(a[nx][ny])) {
                vis[nx][ny] = true;
                dist[nx][ny] = dist[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
}

bool dp[72][N][N][N][N];
bool reach[N][N][N][N];

struct Edge {
    int to, rev, cap;
};
vector<vector<Edge>> g;
vector<int> level, ptr;

void addEdge(int f, int t, int c) {
    g[f].push_back({t, (int)g[t].size(), c});
    g[t].push_back({f, (int)g[f].size() - 1, 0});
}

bool bfsLevel() {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (const Edge& e : g[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[2 * n * n + 1] >= 0;
}

int dfsFlow(int v, int f) {
    if (v == 2 * n * n + 1) return f;
    for (int &i = ptr[v]; i < (int)g[v].size(); ++i) {
        Edge &e = g[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int ret = dfsFlow(e.to, min(f, e.cap));
            if (ret > 0) {
                e.cap -= ret;
                g[e.to][e.rev].cap += ret;
                return ret;
            }
        }
    }
    return 0;
}

void solve() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf(" %s", a[i]);
    for (int i = 0; i < n; ++i) scanf(" %s", b[i]);
    scanf("%d%d", &sx, &sy);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') { sx = i; sy = j; }
    bfsDist();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(a[i][j]))
                dp[0][i][j][i][j] = true;

    for (int yt = 0; yt < t; ++yt) {
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!dp[yt][s1][s2][x][y]) continue;
                        if (dist[x][y] <= yt) continue;
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dx[k], ny = y + dy[k];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < n && isdigit(a[nx][ny]) && dist[nx][ny] >= yt + 1)
                                dp[yt + 1][s1][s2][nx][ny] = true;
                        }
                    }
    }

    for (int yt = 0; yt <= t; ++yt)
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (dp[yt][s1][s2][x][y])
                            reach[s1][s2][x][y] = true;

    int V = 2 * n * n + 2;
    g.assign(V, vector<Edge>());
    level.resize(V);
    ptr.resize(V);

    for (int x = 0; x < n; ++x)
        for (int y = 0; y < n; ++y) {
            if (isdigit(a[x][y]))
                addEdge(0, x * n + y + 1, a[x][y] - '0');
            if (isdigit(b[x][y]))
                addEdge(n * n + x * n + y + 1, 2 * n * n + 1, b[x][y] - '0');
        }

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if (isdigit(a[x1][y1]))
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2)
                        if (isdigit(a[x2][y2]) && reach[x1][y1][x2][y2])
                            addEdge(x1 * n + y1 + 1, n * n + x2 * n + y2 + 1, INF);

    int flow = 0;
    while (bfsLevel()) {
        fill(ptr.begin(), ptr.end(), 0);
        int f;
        while ((f = dfsFlow(0, INF)) > 0)
            flow += f;
    }

    printf("%d\n", flow);
}

int main() {
    solve();
    return 0;
}
