import java.util.*;

public class Main {
    static final int N = 12;
    static final int INF = 1000000009;
    static final int[] dx = {0, 1, 0, -1};
    static final int[] dy = {1, 0, -1, 0};

    static int n, t;
    static char[][] a, b;
    static int sx, sy;
    static int[][] dist;
    static boolean[][][][][] dp;
    static boolean[][][][] reach;
    static List<List<Edge>> g;
    static int[] level, ptr;

    static class Edge {
        int to, rev, cap;
        Edge(int to, int rev, int cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static void addEdge(int f, int t, int c) {
        g.get(f).add(new Edge(t, g.get(t).size(), c));
        g.get(t).add(new Edge(f, g.get(f).size() - 1, 0));
    }

    static boolean bfsLevel() {
        Arrays.fill(level, -1);
        Queue<Integer> q = new LinkedList<>();
        level[0] = 0;
        q.add(0);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : g.get(v)) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.add(e.to);
                }
            }
        }
        return level[2 * n * n + 1] >= 0;
    }

    static int dfsFlow(int v, int f) {
        if (v == 2 * n * n + 1) return f;
        for (int i = ptr[v]; i < g.get(v).size(); ++i) {
            Edge e = g.get(v).get(i);
            if (e.cap > 0 && level[v] < level[e.to]) {
                int ret = dfsFlow(e.to, Math.min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    g.get(e.to).get(e.rev).cap += ret;
                    return ret;
                }
            }
            ptr[v] = i + 1;
        }
        return 0;
    }

    static void bfsDist() {
        dist = new int[n][n];
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist[i], INF);
        boolean[][] vis = new boolean[n][n];
        Queue<int[]> q = new LinkedList<>();
        vis[sx][sy] = true;
        dist[sx][sy] = 0;
        q.add(new int[]{sx, sy});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int x = p[0], y = p[1];
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny] && Character.isDigit(a[nx][ny])) {
                    vis[nx][ny] = true;
                    dist[nx][ny] = dist[x][y] + 1;
                    q.add(new int[]{nx, ny});
                }
            }
        }
    }

    static void solve() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        a = new char[n][n];
        b = new char[n][n];
        for (int i = 0; i < n; ++i) {
            String s = sc.next();
            a[i] = s.toCharArray();
        }
        for (int i = 0; i < n; ++i) {
            String s = sc.next();
            b[i] = s.toCharArray();
        }
        sx = sc.nextInt();
        sy = sc.nextInt();

        // Find 'Z' and set start
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (a[i][j] == 'Z') {
                    sx = i;
                    sy = j;
                }

        bfsDist();

        // DP initialization
        dp = new boolean[72][n][n][n][n];
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (Character.isDigit(a[i][j]))
                    dp[0][i][j][i][j] = true;

        // DP transitions
        for (int yt = 0; yt < t; ++yt) {
            for (int s1 = 0; s1 < n; ++s1)
                for (int s2 = 0; s2 < n; ++s2)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y) {
                            if (!dp[yt][s1][s2][x][y]) continue;
                            if (dist[x][y] <= yt) continue;
                            for (int k = 0; k < 4; ++k) {
                                int nx = x + dx[k], ny = y + dy[k];
                                if (nx >= 0 && nx < n && ny >= 0 && ny < n && Character.isDigit(a[nx][ny]) && dist[nx][ny] >= yt + 1)
                                    dp[yt + 1][s1][s2][nx][ny] = true;
                            }
                        }
        }

        // Reachable states
        reach = new boolean[n][n][n][n];
        for (int yt = 0; yt <= t; ++yt)
            for (int s1 = 0; s1 < n; ++s1)
                for (int s2 = 0; s2 < n; ++s2)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y)
                            if (dp[yt][s1][s2][x][y])
                                reach[s1][s2][x][y] = true;

        // Build flow network
        int V = 2 * n * n + 2;
        g = new ArrayList<>(V);
        for (int i = 0; i < V; ++i) g.add(new ArrayList<>());
        level = new int[V];
        ptr = new int[V];

        // Source to left nodes
        for (int x = 0; x < n; ++x)
            for (int y = 0; y < n; ++y) {
                if (Character.isDigit(a[x][y]))
                    addEdge(0, x * n + y + 1, a[x][y] - '0');
                if (Character.isDigit(b[x][y]))
                    addEdge(n * n + x * n + y + 1, 2 * n * n + 1, b[x][y] - '0');
            }

        // Left to right edges based on reachability
        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                if (Character.isDigit(a[x1][y1]))
                    for (int x2 = 0; x2 < n; ++x2)
                        for (int y2 = 0; y2 < n; ++y2)
                            if (Character.isDigit(a[x2][y2]) && reach[x1][y1][x2][y2])
                                addEdge(x1 * n + y1 + 1, n * n + x2 * n + y2 + 1, INF);

        // Dinic max flow
        int flow = 0;
        while (bfsLevel()) {
            Arrays.fill(ptr, 0);
            int f;
            while ((f = dfsFlow(0, INF)) > 0)
                flow += f;
        }

        System.out.println(flow);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}
